:root {
  --bg: #1e1e2f;
  --card: #2a2a40;
  --text: #f0f0f0;
  --accent: #ffcc00;
  --accent-dark: #cc9900;
  --focus: #66ccff;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: 'Courier New', Courier, monospace;
  font-size: 18px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 0;
  padding: 32px 24px;
  max-width: 400px;
  width: 100%;
  text-align: center;
  box-shadow: 8px 8px 0 rgba(0,0,0,0.4);
}

h1 {
  font-size: 24px;
  margin-bottom: 24px;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--accent);
}

#question {
  font-size: 32px;
  margin-bottom: 32px;
  font-weight: bold;
}

.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

button {
  font-family: inherit;
  font-size: 20px;
  padding: 12px 24px;
  background: var(--accent);
  color: var(--bg);
  border: 3px solid var(--accent);
  border-radius: 0;
  cursor: pointer;
  transition: background 0.1s, transform 0.1s;
  min-width: 80px;
  font-weight: bold;
}

button:hover:not(:disabled) {
  background: var(--accent-dark);
  border-color: var(--accent-dark);
}

button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

button:active:not(:disabled) {
  transform: translate(2px, 2px);
  box-shadow: none;
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

#score {
  font-size: 20px;
  margin-bottom: 24px;
  color: var(--accent);
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

@media (max-width: 360px) {
  .card {
    padding: 24px 16px;
  }
  button {
    padding: 10px 16px;
    font-size: 18px;
    min-width: 70px;
  }
  #question {
    font-size: 28px;
  }
}

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

const questions = [
  { text: '2 + 2 = ?', answers: ['4', '5'], correct: '4' },
  { text: '3 + 3 = ?', answers: ['5', '6'], correct: '6' }
];

let currentQuestion = 0;
let score = 0;
let answered = false;

function renderQuestion() {
  const q = questions[currentQuestion];
  questionEl.textContent = q.text;
  answerA.textContent = q.answers[0];
  answerB.textContent = q.answers[1];
  answerA.disabled = false;
  answerB.disabled = false;
  answered = false;
  scoreEl.textContent = 'Score: ' + score;
}

function handleAnswer(selected) {
  if (answered) return;
  answered = true;
  answerA.disabled = true;
  answerB.disabled = true;
  if (selected === questions[currentQuestion].correct) {
    score++;
    scoreEl.textContent = 'Score: ' + score;
  }
}

answerA.addEventListener('click', () => handleAnswer(answerA.textContent));
answerB.addEventListener('click', () => handleAnswer(answerB.textContent));

nextBtn.addEventListener('click', () => {
  if (!answered) return;
  if (currentQuestion < questions.length - 1) {
    currentQuestion++;
    renderQuestion();
  } else {
    questionEl.textContent = 'Finished';
    answerA.disabled = true;
    answerB.disabled = true;
  }
});

restartBtn.addEventListener('click', () => {
  currentQuestion = 0;
  score = 0;
  renderQuestion();
});

renderQuestion();
